"""Differential checks against results generated by the actual Excel macro.

Each fixture was recorded from a disposable, recalculated workbook copy using
``record_excel_oracle.py``.  Every printed concentration and respiration cell,
not merely selected samples, is compared to the Python solver.
"""

from __future__ import annotations

import json
import math
from pathlib import Path

import pytest

from transportmodel.charts import build_charts
from transportmodel.numerical import run_model


FIXTURES = Path(__file__).parent / "fixtures" / "excel_oracle"


def _cases() -> list[Path]:
    return sorted(FIXTURES.glob("*.json"))


@pytest.mark.parametrize("fixture_path", _cases(), ids=lambda path: path.stem)
def test_all_printed_excel_cells(fixture_path: Path) -> None:
    fixture = json.loads(fixture_path.read_text(encoding="utf-8"))
    assert fixture["source_sha256"]
    assert fixture["dialogs"][-1]["text"].endswith("The Application Ended")
    model = run_model(fixture["config"])
    excel_names = set(fixture["outputs"])
    assert set(model.values) == excel_names
    for name, output in fixture["outputs"].items():
        matrix = output["data"]
        actual = model.values[name]
        assert len(matrix) == len(actual) == len(model.time_seconds)
        assert output["headers"]["cell_numbers"][3:] == list(range(1, len(model.coordinates_m) + 1))
        for i, (excel_x, python_x) in enumerate(zip(output["headers"]["coordinates"][3:], model.coordinates_m)):
            assert math.isclose(excel_x, python_x, rel_tol=1e-14, abs_tol=1e-12), (name, "coordinate", i)
        for time_index, (excel_row, python_row) in enumerate(zip(matrix, actual)):
            assert math.isclose(excel_row[0], model.time_seconds[time_index], abs_tol=1e-12)
            assert math.isclose(excel_row[1], model.time_seconds[time_index] / 86400,
                                rel_tol=1e-14, abs_tol=1e-14)
            assert len(excel_row[3:]) == len(python_row)
            for cell_index, (excel_value, python_value) in enumerate(zip(excel_row[3:], python_row), start=1):
                assert math.isclose(excel_value, python_value, rel_tol=1e-14, abs_tol=1e-12), (
                    fixture_path.stem, name, time_index, cell_index, excel_value, python_value
                )


@pytest.mark.parametrize("fixture_path", _cases(), ids=lambda path: path.stem)
def test_river_diagnostics(fixture_path: Path) -> None:
    fixture = json.loads(fixture_path.read_text(encoding="utf-8"))
    diagnostics = run_model(fixture["config"]).diagnostics
    rows = fixture["river_diagnostics"]
    assert rows[0][2] == diagnostics["courant_number"]
    assert rows[1][2] == diagnostics["diffusion_number"]
    assert rows[2][2] == diagnostics["grid_reynolds_number"]
    assert rows[5][2] == diagnostics["residence_time_river_days"]
    assert rows[6][2] == diagnostics["residence_time_cell_seconds"]


@pytest.mark.parametrize("fixture_path", _cases(), ids=lambda path: path.stem)
def test_excel_chart_series(fixture_path: Path) -> None:
    fixture = json.loads(fixture_path.read_text(encoding="utf-8"))
    result = run_model(fixture["config"])
    charts = build_charts(result, fixture["config"])
    # The macro can chart prior CO2 worksheet contents when DO is active, and
    # omit a calculated CO2 sheet when DO is inactive. Compare every chart
    # whose source is calculated in both runs; the app intentionally charts
    # every calculated property and never reads old workbook contents.
    def reference_source(chart: dict) -> str:
        return chart["series"][0]["formula"].split(",", 2)[1].split("!", 1)[0].strip("'")

    excel_sources = {reference_source(chart) for chart in fixture["graphs"]}
    common_sources = excel_sources.intersection(result.values)
    excel = [chart for chart in fixture["graphs"]
             if reference_source(chart) in common_sources]
    charts = [chart for chart in charts if chart["y_axis_title"] in common_sources]
    assert len(charts) == len(excel)
    for chart, reference in zip(charts, excel):
        for key in ("object_name", "title", "chart_type"):
            assert chart[key] == reference[key], (fixture_path.stem, key)
        assert len(chart["series"]) == len(reference["series"])
        for series, expected in zip(chart["series"], reference["series"]):
            assert series["name"] == expected["name"]
            assert series["formula"] == expected["formula"]
            for field in ("x_values", "y_values"):
                assert len(series[field]) == len(expected[field])
                for py_value, excel_value in zip(series[field], expected[field]):
                    if py_value is None or excel_value is None:
                        assert py_value is excel_value
                    else:
                        assert math.isclose(py_value, excel_value,
                                            rel_tol=1e-14, abs_tol=1e-12)
